1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const neighborsOf = ([x, y]: Cell): Cell[] => [
7	  [x - 1, y - 1],
8	  [x, y - 1],
9	  [x + 1, y - 1],
10	  [x - 1, y],
11	  [x + 1, y],
12	  [x - 1, y + 1],
13	  [x, y + 1],
14	  [x + 1, y + 1],
15	];
16	
17	const isLiving = (cell: Cell, livingCells: Cell[]): boolean =>
18	  livingCells.some((living) => isSameCell(cell, living));
19	
20	const countLivingNeighbors = (cell: Cell, livingCells: Cell[]): number =>
21	  neighborsOf(cell).filter((neighbor) => isLiving(neighbor, livingCells)).length;
22	
23	const dedupeCells = (cells: Cell[]): Cell[] =>
24	  cells.filter(
25	    (cell, index, all) =>
26	      all.findIndex((other) => isSameCell(cell, other)) === index,
27	  );
28	
29	export const nextGeneration = (livingCells: Cell[]): Cell[] => {
30	  const candidates = dedupeCells([
31	    ...livingCells,
32	    ...livingCells.flatMap(neighborsOf),
33	  ]);
34	  return candidates.filter((cell) => {
35	    const livingNeighborCount = countLivingNeighbors(cell, livingCells);
36	    return (
37	      livingNeighborCount === 3 ||
38	      (livingNeighborCount === 2 && isLiving(cell, livingCells))
39	    );
40	  });
41	};
